import { Category, ErrorEvent, Identity, PartyIdentification, UserEngagement } from '../events';
/**
Description: View a page.
*/
export type ViewPage = {
    events: Array<UserEngagement | Identity | PartyIdentification | ErrorEvent>;
}

export class ViewPageBuilder {

    private viewPage: ViewPage = {
        events: []
    }

    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;
    private userEngagement!: UserEngagement;

    public withErrorEvent(errorEvent: ErrorEvent) : ViewPageBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ViewPageBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ViewPageBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }
    public withUserEngagement(userEngagement: UserEngagement) : ViewPageBuilder {
        this.userEngagement = userEngagement;
        return this;
    }

    public build() : ViewPage {
        if(this.errorEvent) {
            this.viewPage.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.viewPage.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.viewPage.events.push(this.partyIdentification);
        }
        if(this.userEngagement) {
            this.viewPage.events.push(this.userEngagement);
        }

        return this.viewPage;
    }
}
